-- 40-verify-counts.sql · 迁移前后行数与内容校验和核对
-- 只读核对：逐张迁移表比较旧侧（含拆分条件）与新侧的行数及按共同列计算的行校验和（CRC32 的 BIT_XOR 与 SUM）。
-- 另核对：每个旧库全部行都有去处（按表行数 = 各去处之和 + 归档），未登记的补偿事件类型 / BCR 类型为 0。
-- 输出列：check_name、old_rows、new_rows、result（行数与两种校验和都相同才为 OK）。任一 MISMATCH 即迁移不通过。
-- 只输出计数与校验和，不输出任何业务值。由 scripts/migrate.sh verify 执行；可重复执行。

SET NAMES utf8mb4;
SET time_zone = '+00:00';

SELECT 'mor_cct.t_agreement->mor_commercial' AS check_name, o.row_count AS old_rows, n.row_count AS new_rows,
       IF(o.row_count = n.row_count AND o.row_xor = n.row_xor AND o.row_sum = n.row_sum, 'OK', 'MISMATCH') AS result
  FROM (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`agreement_id`, '\\N'), IFNULL(`agreement_no`, '\\N'), IFNULL(`agreement_name`, '\\N'), IFNULL(`agreement_type`, '\\N'), IFNULL(`client_id`, '\\N'), IFNULL(`local_partner_id`, '\\N'), IFNULL(`entity_no`, '\\N'), IFNULL(`agreement_format`, '\\N'), IFNULL(`status`, '\\N'), IFNULL(`effective_from`, '\\N'), IFNULL(`effective_to`, '\\N'), IFNULL(`signed_time`, '\\N'), IFNULL(`activated_time`, '\\N'), IFNULL(`create_by`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`agreement_id`, '\\N'), IFNULL(`agreement_no`, '\\N'), IFNULL(`agreement_name`, '\\N'), IFNULL(`agreement_type`, '\\N'), IFNULL(`client_id`, '\\N'), IFNULL(`local_partner_id`, '\\N'), IFNULL(`entity_no`, '\\N'), IFNULL(`agreement_format`, '\\N'), IFNULL(`status`, '\\N'), IFNULL(`effective_from`, '\\N'), IFNULL(`effective_to`, '\\N'), IFNULL(`signed_time`, '\\N'), IFNULL(`activated_time`, '\\N'), IFNULL(`create_by`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_cct`.`t_agreement`) o
  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`agreement_id`, '\\N'), IFNULL(`agreement_no`, '\\N'), IFNULL(`agreement_name`, '\\N'), IFNULL(`agreement_type`, '\\N'), IFNULL(`client_id`, '\\N'), IFNULL(`local_partner_id`, '\\N'), IFNULL(`entity_no`, '\\N'), IFNULL(`agreement_format`, '\\N'), IFNULL(`status`, '\\N'), IFNULL(`effective_from`, '\\N'), IFNULL(`effective_to`, '\\N'), IFNULL(`signed_time`, '\\N'), IFNULL(`activated_time`, '\\N'), IFNULL(`create_by`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`agreement_id`, '\\N'), IFNULL(`agreement_no`, '\\N'), IFNULL(`agreement_name`, '\\N'), IFNULL(`agreement_type`, '\\N'), IFNULL(`client_id`, '\\N'), IFNULL(`local_partner_id`, '\\N'), IFNULL(`entity_no`, '\\N'), IFNULL(`agreement_format`, '\\N'), IFNULL(`status`, '\\N'), IFNULL(`effective_from`, '\\N'), IFNULL(`effective_to`, '\\N'), IFNULL(`signed_time`, '\\N'), IFNULL(`activated_time`, '\\N'), IFNULL(`create_by`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_commercial`.`t_agreement`) n
UNION ALL
SELECT 'mor_cct.t_agreement_document_ref->mor_commercial' AS check_name, o.row_count AS old_rows, n.row_count AS new_rows,
       IF(o.row_count = n.row_count AND o.row_xor = n.row_xor AND o.row_sum = n.row_sum, 'OK', 'MISMATCH') AS result
  FROM (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`agreement_document_id`, '\\N'), IFNULL(`agreement_id`, '\\N'), IFNULL(`document_type`, '\\N'), IFNULL(`file_id`, '\\N'), IFNULL(`content_hash`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`agreement_document_id`, '\\N'), IFNULL(`agreement_id`, '\\N'), IFNULL(`document_type`, '\\N'), IFNULL(`file_id`, '\\N'), IFNULL(`content_hash`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_cct`.`t_agreement_document_ref`) o
  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`agreement_document_id`, '\\N'), IFNULL(`agreement_id`, '\\N'), IFNULL(`document_type`, '\\N'), IFNULL(`file_id`, '\\N'), IFNULL(`content_hash`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`agreement_document_id`, '\\N'), IFNULL(`agreement_id`, '\\N'), IFNULL(`document_type`, '\\N'), IFNULL(`file_id`, '\\N'), IFNULL(`content_hash`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_commercial`.`t_agreement_document_ref`) n
UNION ALL
