  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`agreement_operating_entity_id`, '\\N'), IFNULL(`agreement_id`, '\\N'), IFNULL(`entity_no`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`agreement_operating_entity_id`, '\\N'), IFNULL(`agreement_id`, '\\N'), IFNULL(`entity_no`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_commercial`.`t_agreement_operating_entity`) n
