  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`agreement_party_id`, '\\N'), IFNULL(`agreement_id`, '\\N'), IFNULL(`party_id`, '\\N'), IFNULL(`party_profile_id`, '\\N'), IFNULL(`party_role`, '\\N'), IFNULL(`acceptance_method`, '\\N'), IFNULL(`accepted_by_actor_id`, '\\N'), IFNULL(`accepted_time`, '\\N'), IFNULL(`evidence_document_id`, '\\N'), IFNULL(`acceptance_reference`, '\\N'), IFNULL(`acceptance_ref_slot`, '\\N'), IFNULL(`acceptance_recorded_by`, '\\N'), IFNULL(`acceptance_recorded_at`, '\\N'), IFNULL(`create_by`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`agreement_party_id`, '\\N'), IFNULL(`agreement_id`, '\\N'), IFNULL(`party_id`, '\\N'), IFNULL(`party_profile_id`, '\\N'), IFNULL(`party_role`, '\\N'), IFNULL(`acceptance_method`, '\\N'), IFNULL(`accepted_by_actor_id`, '\\N'), IFNULL(`accepted_time`, '\\N'), IFNULL(`evidence_document_id`, '\\N'), IFNULL(`acceptance_reference`, '\\N'), IFNULL(`acceptance_ref_slot`, '\\N'), IFNULL(`acceptance_recorded_by`, '\\N'), IFNULL(`acceptance_recorded_at`, '\\N'), IFNULL(`create_by`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_commercial`.`t_agreement_party`) n
UNION ALL
SELECT 'mor_cct.t_application_document->mor_client_master' AS check_name, o.row_count AS old_rows, n.row_count AS new_rows,
       IF(o.row_count = n.row_count AND o.row_xor = n.row_xor AND o.row_sum = n.row_sum, 'OK', 'MISMATCH') AS result
  FROM (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`document_id`, '\\N'), IFNULL(`client_application_id`, '\\N'), IFNULL(`partner_application_id`, '\\N'), IFNULL(`operating_entity_application_id`, '\\N'), IFNULL(`subject_party_id`, '\\N'), IFNULL(`requirement_code`, '\\N'), IFNULL(`document_type`, '\\N'), IFNULL(`file_id`, '\\N'), IFNULL(`content_hash`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`document_id`, '\\N'), IFNULL(`client_application_id`, '\\N'), IFNULL(`partner_application_id`, '\\N'), IFNULL(`operating_entity_application_id`, '\\N'), IFNULL(`subject_party_id`, '\\N'), IFNULL(`requirement_code`, '\\N'), IFNULL(`document_type`, '\\N'), IFNULL(`file_id`, '\\N'), IFNULL(`content_hash`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_cct`.`t_application_document`) o
  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`document_id`, '\\N'), IFNULL(`client_application_id`, '\\N'), IFNULL(`partner_application_id`, '\\N'), IFNULL(`operating_entity_application_id`, '\\N'), IFNULL(`subject_party_id`, '\\N'), IFNULL(`requirement_code`, '\\N'), IFNULL(`document_type`, '\\N'), IFNULL(`file_id`, '\\N'), IFNULL(`content_hash`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`document_id`, '\\N'), IFNULL(`client_application_id`, '\\N'), IFNULL(`partner_application_id`, '\\N'), IFNULL(`operating_entity_application_id`, '\\N'), IFNULL(`subject_party_id`, '\\N'), IFNULL(`requirement_code`, '\\N'), IFNULL(`document_type`, '\\N'), IFNULL(`file_id`, '\\N'), IFNULL(`content_hash`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_client_master`.`t_application_document`) n
