  FROM (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`history_id`, '\\N'), IFNULL(`record_type`, '\\N'), IFNULL(`record_id`, '\\N'), IFNULL(`aggregate_root_type`, '\\N'), IFNULL(`aggregate_root_id`, '\\N'), IFNULL(`parent_history_id`, '\\N'), IFNULL(`current_version`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`history_id`, '\\N'), IFNULL(`record_type`, '\\N'), IFNULL(`record_id`, '\\N'), IFNULL(`aggregate_root_type`, '\\N'), IFNULL(`aggregate_root_id`, '\\N'), IFNULL(`parent_history_id`, '\\N'), IFNULL(`current_version`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_cct`.`t_business_change_record` WHERE `record_type` IN ('PARTY', 'CLIENT', 'LOCAL_PARTNER', 'OPERATING_ENTITY', 'PARTY_PROFILE', 'CLIENT_BUSINESS_PROFILE', 'CLIENT_APPLICATION', 'PARTNER_APPLICATION', 'OPERATING_ENTITY_APPLICATION', 'PARTY_RELATION', 'CLIENT_ENTITY_AFFILIATION', 'ENTITY_SOURCE_RELATION', 'CONSUMER_LEGAL_DOCUMENT', 'SELLER_DISCLOSURE')) o
  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`history_id`, '\\N'), IFNULL(`record_type`, '\\N'), IFNULL(`record_id`, '\\N'), IFNULL(`aggregate_root_type`, '\\N'), IFNULL(`aggregate_root_id`, '\\N'), IFNULL(`parent_history_id`, '\\N'), IFNULL(`current_version`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`history_id`, '\\N'), IFNULL(`record_type`, '\\N'), IFNULL(`record_id`, '\\N'), IFNULL(`aggregate_root_type`, '\\N'), IFNULL(`aggregate_root_id`, '\\N'), IFNULL(`parent_history_id`, '\\N'), IFNULL(`current_version`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_client_master`.`t_business_change_record`) n
UNION ALL
SELECT 'mor_cct.t_business_change_record->mor_commercial [split]' AS check_name, o.row_count AS old_rows, n.row_count AS new_rows,
       IF(o.row_count = n.row_count AND o.row_xor = n.row_xor AND o.row_sum = n.row_sum, 'OK', 'MISMATCH') AS result
  FROM (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`history_id`, '\\N'), IFNULL(`record_type`, '\\N'), IFNULL(`record_id`, '\\N'), IFNULL(`aggregate_root_type`, '\\N'), IFNULL(`aggregate_root_id`, '\\N'), IFNULL(`parent_history_id`, '\\N'), IFNULL(`current_version`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`history_id`, '\\N'), IFNULL(`record_type`, '\\N'), IFNULL(`record_id`, '\\N'), IFNULL(`aggregate_root_type`, '\\N'), IFNULL(`aggregate_root_id`, '\\N'), IFNULL(`parent_history_id`, '\\N'), IFNULL(`current_version`, '\\N'), IFNULL(`create_time`, '\\N'), IFNULL(`update_time`, '\\N')))), 0) AS row_sum FROM `mor_cct`.`t_business_change_record` WHERE `record_type` IN ('COMMERCIAL_TERM_VERSION', 'AGREEMENT', 'COMMERCIAL_TERM_PLAN', 'PAYMENT_METHOD_PROFILE')) o
