  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`change_version_id`, '\\N'), IFNULL(`history_id`, '\\N'), IFNULL(`version_no`, '\\N'), IFNULL(`operation_type`, '\\N'), IFNULL(`snapshot_json`, '\\N'), IFNULL(`snapshot_format`, '\\N'), IFNULL(`create_by`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`change_version_id`, '\\N'), IFNULL(`history_id`, '\\N'), IFNULL(`version_no`, '\\N'), IFNULL(`operation_type`, '\\N'), IFNULL(`snapshot_json`, '\\N'), IFNULL(`snapshot_format`, '\\N'), IFNULL(`create_by`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_sum FROM `mor_commercial`.`t_business_change_version`) n
