  FROM (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`event_subject_id`, '\\N'), IFNULL(`velocity_event_id`, '\\N'), IFNULL(`subject_type`, '\\N'), IFNULL(`subject_key`, '\\N'), IFNULL(`event_code`, '\\N'), IFNULL(`occurred_time`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`event_subject_id`, '\\N'), IFNULL(`velocity_event_id`, '\\N'), IFNULL(`subject_type`, '\\N'), IFNULL(`subject_key`, '\\N'), IFNULL(`event_code`, '\\N'), IFNULL(`occurred_time`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_sum FROM `mor_risk`.`t_velocity_event_subject`) o
  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`event_subject_id`, '\\N'), IFNULL(`velocity_event_id`, '\\N'), IFNULL(`subject_type`, '\\N'), IFNULL(`subject_key`, '\\N'), IFNULL(`event_code`, '\\N'), IFNULL(`occurred_time`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`event_subject_id`, '\\N'), IFNULL(`velocity_event_id`, '\\N'), IFNULL(`subject_type`, '\\N'), IFNULL(`subject_key`, '\\N'), IFNULL(`event_code`, '\\N'), IFNULL(`occurred_time`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_sum FROM `mor_risk_decision`.`t_velocity_event_subject`) n
UNION ALL
SELECT 'mor_risk.t_velocity_feature_definition->mor_risk_decision' AS check_name, o.row_count AS old_rows, n.row_count AS new_rows,
       IF(o.row_count = n.row_count AND o.row_xor = n.row_xor AND o.row_sum = n.row_sum, 'OK', 'MISMATCH') AS result
  FROM (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`feature_version_id`, '\\N'), IFNULL(`event_code`, '\\N'), IFNULL(`anchor_subject_type`, '\\N'), IFNULL(`metric`, '\\N'), IFNULL(`distinct_subject_type`, '\\N'), IFNULL(`window_seconds`, '\\N'), IFNULL(`include_current`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`feature_version_id`, '\\N'), IFNULL(`event_code`, '\\N'), IFNULL(`anchor_subject_type`, '\\N'), IFNULL(`metric`, '\\N'), IFNULL(`distinct_subject_type`, '\\N'), IFNULL(`window_seconds`, '\\N'), IFNULL(`include_current`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_sum FROM `mor_risk`.`t_velocity_feature_definition`) o
  CROSS JOIN (SELECT COUNT(*) AS row_count, IFNULL(BIT_XOR(CRC32(CONCAT_WS('|', IFNULL(`feature_version_id`, '\\N'), IFNULL(`event_code`, '\\N'), IFNULL(`anchor_subject_type`, '\\N'), IFNULL(`metric`, '\\N'), IFNULL(`distinct_subject_type`, '\\N'), IFNULL(`window_seconds`, '\\N'), IFNULL(`include_current`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_xor, IFNULL(SUM(CRC32(CONCAT_WS('|', IFNULL(`feature_version_id`, '\\N'), IFNULL(`event_code`, '\\N'), IFNULL(`anchor_subject_type`, '\\N'), IFNULL(`metric`, '\\N'), IFNULL(`distinct_subject_type`, '\\N'), IFNULL(`window_seconds`, '\\N'), IFNULL(`include_current`, '\\N'), IFNULL(`create_time`, '\\N')))), 0) AS row_sum FROM `mor_risk_decision`.`t_velocity_feature_definition`) n
UNION ALL
